mapper.select:
SELECT 
    C.CODE_ID AS upperCodeId,
    M.MESSAGE_CN AS upperCodeName
FROM CM_CODE C
LEFT JOIN CM_MESSAGE_LANG M 
    ON M.CMPNY_CD = C.CMPNY_CD
    AND M.LANG_KEY = C.CODE_LANG_KEY 
    AND M.LANG_CODE = #{langGb}
WHERE C.CMPNY_CD = #{cmpnyCd}
  AND C.CODE_ID = #{codeId}

mapper.delete:
DELETE FROM CM_CODE 
WHERE CMPNY_CD = #{cmpnyCd}
  AND CODE_ID = #{codeId}

DELETE FROM CM_CODE_DETAIL 
WHERE CMPNY_CD = #{cmpnyCd}
  AND CODE_ID = #{codeId}
